import {useState} from 'react';
import {createPracticeResource} from '../../lib/practiceOperationsApi';

export function EmbeddedConsultationForm({config,clients,onSaved}){
  const [form,setForm]=useState({client_id:clients[0]?.id||'',title:'',due_at:'',sessionType:'INITIAL',presentingConcern:''});
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const change=key=>event=>setForm(current=>({...current,[key]:event.target.value}));
  const submit=async event=>{event.preventDefault();setBusy(true);setError('');try{await createPracticeResource('consultations',{client_id:form.client_id,type:config.type,title:form.title,status:config.status,due_at:form.due_at,payload:{source:'CONSULTANT_ENTERED',sessionType:form.sessionType,presentingConcern:form.presentingConcern}});await onSaved();}catch(reason){setError(reason.message||'Consultation could not be scheduled.');setBusy(false)}};
  return <form onSubmit={submit} className="rounded-3xl border bg-white p-5 sm:p-7"><h3 className="text-xl font-bold">{config.create}</h3><p className="mt-1 text-sm text-slate-500">Schedule directly on the page. The saved record appears in Consultation records.</p>{error&&<p role="alert" className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}<div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold">Client<select required value={form.client_id} onChange={change('client_id')} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="">Select client</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label><label className="text-sm font-semibold">Date and time<input required type="datetime-local" value={form.due_at} onChange={change('due_at')} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label><label className="text-sm font-semibold sm:col-span-2">Title<input required value={form.title} onChange={change('title')} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label><label className="text-sm font-semibold">Session type<select value={form.sessionType} onChange={change('sessionType')} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="INITIAL">Initial</option><option value="FOLLOW_UP">Follow-up</option><option value="REVIEW">Review</option><option value="ASSESSMENT">Assessment</option><option value="THERAPY">Therapy</option><option value="COACHING">Coaching</option><option value="OTHER">Other</option></select></label><label className="text-sm font-semibold">Presenting concern<textarea value={form.presentingConcern} onChange={change('presentingConcern')} className="mt-2 min-h-24 w-full rounded-xl border p-3"/></label></div><button disabled={busy} className="mt-6 min-h-12 rounded-xl bg-blue-700 px-6 font-bold text-white disabled:opacity-50">{busy?'Scheduling…':'Schedule consultation'}</button></form>;
}
